import AppKit

@available(macOS 27.0, *)
final class GlassPanelController: NSViewController {
    override func loadView() {
        let label = NSTextField(labelWithString: "MindLearn")
        label.font = .preferredFont(forTextStyle: .title2)

        let glassView = NSGlassEffectView()
        glassView.contentView = label
        glassView.translatesAutoresizingMaskIntoConstraints = false

        let rootView = NSView()
        rootView.addSubview(glassView)
        NSLayoutConstraint.activate([
            glassView.centerXAnchor.constraint(equalTo: rootView.centerXAnchor),
            glassView.centerYAnchor.constraint(equalTo: rootView.centerYAnchor),
            glassView.widthAnchor.constraint(greaterThanOrEqualToConstant: 240),
            glassView.heightAnchor.constraint(greaterThanOrEqualToConstant: 80)
        ])
        view = rootView
    }
}

