import AppKit

struct Topic: Hashable {
    let id: UUID
    let title: String
}

let dataSource = NSOutlineViewDiffableDataSource<String, Topic>(outlineView: outlineView) { outlineView, tableColumn, topic in
    let identifier = NSUserInterfaceItemIdentifier("TopicCell")
    let cell = outlineView.makeView(withIdentifier: identifier, owner: nil) as? NSTableCellView ?? NSTableCellView()
    cell.identifier = identifier
    cell.textField?.stringValue = topic.title
    return cell
}

